package httpapi
import("errors";"net/http";"time";"github.com/gin-gonic/gin";"github.com/sagarbagwe/jobapply-ai/backend/internal/ai";"github.com/sagarbagwe/jobapply-ai/backend/internal/model";"github.com/sagarbagwe/jobapply-ai/backend/internal/security")
func Router(p ai.Provider)*gin.Engine{r:=gin.New();r.Use(gin.Logger(),gin.Recovery(),security.Headers(),security.BodyLimit(15<<20),security.RateLimit(60,time.Minute));r.GET("/healthz",func(c *gin.Context){c.JSON(http.StatusOK,gin.H{"status":"ok"})});v:=r.Group("/v1",security.APIKey());v.POST("/match",func(c *gin.Context){var x model.MatchRequest;if bind(c,&x)!=nil||x.Job.Description==""{bad(c);return};o,e:=p.Match(c,x);respond(c,o,e)});v.POST("/answers",func(c *gin.Context){var x model.AnswerRequest;if bind(c,&x)!=nil||x.Question==""{bad(c);return};o,e:=p.Answer(c,x);respond(c,o,e)});v.POST("/resumes/parse",func(c *gin.Context){var x model.ParseResumeRequest;if bind(c,&x)!=nil||x.Data==""||len(x.Data)>14_000_000{bad(c);return};o,e:=p.ParseResume(c,x);respond(c,o,e)});v.POST("/resumes/recommend",func(c *gin.Context){var x model.RecommendRequest;if bind(c,&x)!=nil||len(x.Resumes)==0{bad(c);return};o,e:=p.RecommendResume(c,x);respond(c,o,e)});return r}
func bind(c *gin.Context,v any)error{return c.ShouldBindJSON(v)};func bad(c *gin.Context){c.JSON(http.StatusBadRequest,gin.H{"error":"invalid request"})};func respond(c *gin.Context,o any,e error){if e==nil{c.JSON(http.StatusOK,o);return};if errors.Is(e,ai.ErrNotConfigured){c.JSON(http.StatusServiceUnavailable,gin.H{"error":"AI provider not configured"});return};c.JSON(http.StatusBadGateway,gin.H{"error":"AI provider request failed"})}
